import {WORLD,ALT_BASE,elevation,lake,streamX,farStreamX,trailX,biomes,biomeAt,destinations,clamp,mix} from './math.js';
const $=id=>document.getElementById(id),TAU=Math.PI*2;
export class AlpineMap{
 constructor(goTo,openFull){this.goTo=goTo;this.openFull=openFull;this.base=document.createElement('canvas');this.base.width=256;this.base.height=320;this.mini={zoom:7,follow:true,x:0,z:-8192};this.full={zoom:1,follow:false,x:0,z:-8192};this.player={x:-44,z:63};this.yaw=0;this.points=[];this.ready=false;this.install();}
 async build(){let c=this.base,w=c.width,h=c.height,heights=new Float32Array(w*h);for(let y=0;y<h;y++){let z=mix(WORLD.minZ,WORLD.maxZ,y/(h-1));for(let x=0;x<w;x++)heights[y*w+x]=elevation(mix(WORLD.minX,WORLD.maxX,x/(w-1)),z);if(y%40===0)await new Promise(r=>setTimeout(r,0))}let ctx=c.getContext('2d'),im=ctx.createImageData(w,h),colors=[[102,132,107],[145,161,127],[180,177,133],[170,169,152],[225,232,226]];for(let y=0;y<h;y++)for(let x=0;x<w;x++){let k=y*w+x,alt=ALT_BASE+heights[k],i=biomes.findIndex(b=>alt<b.max);if(i<0)i=4;let color=colors[i],dx=(heights[y*w+Math.min(w-1,x+1)]-heights[y*w+Math.max(0,x-1)])/128,dz=(heights[Math.min(h-1,y+1)*w+x]-heights[Math.max(0,y-1)*w+x])/128,shade=clamp(.96-dx*.32-dz*.25,.58,1.22);let contour=Math.floor(heights[k]/200)!==Math.floor(heights[y*w+Math.max(0,x-1)]/200);for(let j=0;j<3;j++)im.data[k*4+j]=color[j]*shade*(contour?.82:1);im.data[k*4+3]=255}ctx.putImageData(im,0,0);this.ready=true;}
 install(){
  for(let [id,v,m]of[['miniZoomIn',this.mini,1.5],['miniZoomOut',this.mini,1/1.5],['mapZoomIn',this.full,1.5],['mapZoomOut',this.full,1/1.5]])$(id).onclick=()=>{v.zoom=clamp(v.zoom*m,1,28);this.redraw()};
  $('miniFit').onclick=()=>{this.mini.zoom=1;this.mini.follow=false;this.mini.x=0;this.mini.z=(WORLD.minZ+WORLD.maxZ)/2;this.redraw()};
  $('miniFollow').onclick=()=>{this.mini.follow=true;this.mini.zoom=Math.max(4,this.mini.zoom);this.redraw()};
  $('miniFull').onclick=this.openFull;
  $('mapFit').onclick=()=>{this.full.zoom=1;this.full.follow=false;this.full.x=0;this.full.z=(WORLD.minZ+WORLD.maxZ)/2;this.redraw()};
  $('mapFollow').onclick=()=>{this.full.follow=true;this.full.zoom=6;this.redraw()};
  for(let [id,v]of[['miniCanvas',this.mini],['mapCanvas',this.full]]){
   let c=$(id),drag=null,dist=0;
   c.addEventListener('wheel',e=>{e.preventDefault();let r=c.getBoundingClientRect(),px=(e.clientX-r.left)/r.width*c.width,py=(e.clientY-r.top)/r.height*c.height,before=this.screenToWorld(c,v,px,py);v.zoom=clamp(v.zoom*(e.deltaY<0?1.25:.8),1,28);if(!v.follow){let after=this.screenToWorld(c,v,px,py);v.x+=before.x-after.x;v.z+=before.z-after.z}this.redraw()},{passive:false});
   c.addEventListener('pointerdown',e=>{c.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY};dist=0});
   c.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;dist+=Math.abs(dx)+Math.abs(dy);let r=c.getBoundingClientRect(),t=this.transform(c,v);if(v.follow){v.x=this.player.x;v.z=this.player.z;v.follow=false}v.x-=dx/r.width*c.width/t.s;v.z-=dy/r.height*c.height/t.s;v.x=clamp(v.x,WORLD.minX-2000,WORLD.maxX+2000);v.z=clamp(v.z,WORLD.minZ-2000,WORLD.maxZ+2000);drag.x=e.clientX;drag.y=e.clientY;this.redraw()});
   c.addEventListener('pointerup',e=>{if(!drag)return;if(dist<7&&id==='mapCanvas'){let r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*c.width,y=(e.clientY-r.top)/r.height*c.height;let p=this.points.find(p=>Math.hypot(x-p.x,y-p.y)<14);if(p)this.goTo(p.d.id)}drag=null});c.addEventListener('pointercancel',()=>drag=null);
  }
 }
 transform(c,v){let s=Math.min((c.width-26)/WORLD.width,(c.height-26)/WORLD.height)*v.zoom;let x=v.follow?this.player.x:v.x,z=v.follow?this.player.z:v.z;return{s,x,z,sx:a=>c.width/2+(a-x)*s,sz:a=>c.height/2+(a-z)*s}}
 screenToWorld(c,v,x,y){let t=this.transform(c,v);return{x:t.x+(x-c.width/2)/t.s,z:t.z+(y-c.height/2)/t.s}}
 draw(player,yaw,entered=true){this.player={x:player.x,z:player.z};this.yaw=yaw;if(!this.ready)return;if(entered&&!$('miniMap').hidden)this.paint($('miniCanvas'),this.mini,true);if(!$('mapPanel').hidden)this.paint($('mapCanvas'),this.full,false);$('miniCaption').textContent=`${Math.round(ALT_BASE+elevation(player.x,player.z)).toLocaleString()} m · ${biomeAt(player.x,player.z).name}`;$('miniZoomLevel').textContent=this.mini.zoom.toFixed(1)+'×';$('miniCanvas').setAttribute('aria-label','实时小地图，缩放 '+this.mini.zoom.toFixed(1)+' 倍');$('miniFollow').setAttribute('aria-pressed',String(this.mini.follow));$('miniFollow').classList.toggle('selected',this.mini.follow);$('mapFollow').classList.toggle('selected',this.full.follow)}
 redraw(){this.draw(this.player,this.yaw,true)}
 paint(c,v,mini){let ctx=c.getContext('2d'),w=c.width,h=c.height,t=this.transform(c,v),sx=t.sx,sz=t.sz;ctx.fillStyle='#e7ecdf';ctx.fillRect(0,0,w,h);ctx.save();ctx.beginPath();ctx.rect(0,0,w,h);ctx.clip();ctx.imageSmoothingEnabled=true;ctx.drawImage(this.base,sx(WORLD.minX),sz(WORLD.minZ),WORLD.width*t.s,WORLD.height*t.s);
  const waterLine=(start,end,xAt)=>{ctx.beginPath();for(let z=start;z<=end;z+=90)ctx.lineTo(sx(xAt(z)),sz(z));ctx.stroke()};ctx.strokeStyle='#91bbc2';ctx.lineWidth=Math.max(mini?1.6:2,12*t.s);waterLine(-5880,850,streamX);waterLine(-16400,-13900,farStreamX);ctx.fillStyle='#80aeb9';ctx.beginPath();ctx.ellipse(sx(lake.x),sz(lake.z),Math.max(1,lake.rx*t.s),Math.max(1,lake.rz*t.s),0,0,TAU);ctx.fill();
  ctx.strokeStyle='#f4ead1';ctx.lineWidth=mini?2.5:4;ctx.beginPath();for(let z=70;z>=-15800;z-=60)ctx.lineTo(sx(trailX(z)),sz(z));ctx.stroke();ctx.strokeStyle='#ab8962';ctx.lineWidth=mini?1:1.5;ctx.setLineDash([4,4]);ctx.stroke();ctx.setLineDash([]);
  this.points=mini?this.points:[];let main=new Set(['village','lake','pass','summit','waterfall','northvillage']);
  for(let [i,d]of destinations.entries()){let x=sx(d.x),y=sz(d.z);if(x<-20||x>w+20||y<-20||y>h+20)continue;if(!mini)this.points.push({d,x,y});ctx.fillStyle=d.id==='pass'?'#a78c67':'#f6f3e7';ctx.strokeStyle='#556e51';ctx.lineWidth=1;ctx.beginPath();if(d.id==='summit'){ctx.moveTo(x,y-5);ctx.lineTo(x+5,y+4);ctx.lineTo(x-5,y+4);ctx.closePath()}else ctx.arc(x,y,mini?2.8:4.6,0,TAU);ctx.fill();ctx.stroke();if((!mini&&(main.has(d.id)||v.zoom>2))||(mini&&v.zoom>3&&main.has(d.id))){ctx.font=mini?'10px system-ui':'12px system-ui';ctx.textAlign='center';let dy=i%2?16:-12;ctx.lineWidth=3;ctx.strokeStyle='#ecf0e4d9';ctx.strokeText(d.name,x,y+dy);ctx.fillStyle='#35543f';ctx.fillText(d.name,x,y+dy)}}
  let px=sx(this.player.x),py=sz(this.player.z);ctx.translate(px,py);ctx.rotate(-this.yaw);ctx.fillStyle='#b36f46';ctx.strokeStyle='#fff7e8';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,-(mini?8:10));ctx.lineTo(5,6);ctx.lineTo(0,3);ctx.lineTo(-5,6);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();
  ctx.textAlign='left';ctx.font=mini?'10px system-ui':'11px system-ui';ctx.fillStyle='#355d45';ctx.fillText('N ↑',w-31,21);let lengths=[10,20,50,100,200,500,1000,2000,5000,10000],meters=lengths.reduce((a,b)=>Math.abs(b*t.s-55)<Math.abs(a*t.s-55)?b:a,100),bw=meters*t.s;ctx.strokeStyle='#50684c';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(12,h-19);ctx.lineTo(12+bw,h-19);ctx.moveTo(12,h-22);ctx.lineTo(12,h-16);ctx.moveTo(12+bw,h-22);ctx.lineTo(12+bw,h-16);ctx.stroke();ctx.fillText(meters>=1000?`${meters/1000} km`:`${meters} m`,12,h-26);if(!mini){ctx.textAlign='right';ctx.fillStyle='#597153';ctx.fillText(`缩放 ${v.zoom.toFixed(1)}× · ${Math.round(WORLD.width/1000)} × ${Math.round(WORLD.height/1000)} km`,w-13,h-13)}ctx.textAlign='start';
 }
}
